{
  "name": "点状选区图形组件",
  "name_en": "Spot Selection Graphic Component",
  "manufacturer": "Nion",
  "description": "用于科学图像或数据界面中的非物理图形组件，表示一个可编辑的点状选区。它支持边界、中心、尺寸、旋转、区域与掩膜对象生成，以及命中测试、拖拽调整、微调和序列化，常用于显微数据分析中的交互式标注与掩膜定义。",
  "description_en": "A non-physical graphical component for scientific image or data interfaces that represents an editable spot-shaped selection. It supports bounds, center, size, rotation, region and mask generation, hit testing, drag adjustment, nudging, and serialization, and is used for interactive annotation and mask definition in microscopy data analysis workflows.",
  "tag_hints": [
    "graphical ROI",
    "spot region",
    "image annotation",
    "mask generation",
    "hit testing",
    "drag interaction",
    "microscopy data analysis"
  ],
  "actions": [
    {
      "action_name": "auto-bounds",
      "description": "获取或设置图形边界",
      "description_en": "Get or set the graphic bounds."
    },
    {
      "action_name": "auto-rotation",
      "description": "获取或设置图形旋转角度",
      "description_en": "Get or set the graphic rotation."
    },
    {
      "action_name": "auto-mime_data_dict",
      "description": "导出图形的 MIME 数据字典",
      "description_en": "Export the graphic MIME data dictionary."
    },
    {
      "action_name": "auto-read_from_mime_data",
      "description": "从 MIME 数据字典读取并恢复图形",
      "description_en": "Read and restore the graphic from a MIME data dictionary."
    },
    {
      "action_name": "auto-get_attributes",
      "description": "获取图形属性",
      "description_en": "Get the graphic attributes."
    },
    {
      "action_name": "auto-used_role",
      "description": "获取图形使用的角色",
      "description_en": "Get the role used by the graphic."
    },
    {
      "action_name": "auto-center",
      "description": "获取或设置点状选区中心",
      "description_en": "Get or set the center of the spot selection."
    },
    {
      "action_name": "auto-size",
      "description": "获取或设置点状选区尺寸",
      "description_en": "Get or set the size of the spot selection."
    },
    {
      "action_name": "auto-get_region",
      "description": "获取对应的区域对象",
      "description_en": "Get the corresponding region object."
    },
    {
      "action_name": "auto-get_mask_item",
      "description": "获取对应的掩膜项",
      "description_en": "Get the corresponding mask item."
    },
    {
      "action_name": "auto-test",
      "description": "测试给定点是否命中图形或其可编辑部件",
      "description_en": "Test whether a given point hits the graphic or one of its editable parts."
    },
    {
      "action_name": "auto-begin_drag",
      "description": "开始拖拽交互",
      "description_en": "Begin a drag interaction."
    },
    {
      "action_name": "auto-end_drag",
      "description": "结束拖拽交互",
      "description_en": "End a drag interaction."
    },
    {
      "action_name": "auto-adjust_part",
      "description": "在拖拽过程中调整图形部件",
      "description_en": "Adjust a graphic part during dragging."
    },
    {
      "action_name": "auto-nudge",
      "description": "按位移量微调图形位置",
      "description_en": "Nudge the graphic position by a delta."
    },
    {
      "action_name": "auto-label_position",
      "description": "计算标签显示位置",
      "description_en": "Compute the label display position."
    }
  ]
}

